// Accept body from webhook (n8n v2 webhook puts data under .body)
const body = $input.item.json.body || $input.item.json;

const anomalies = Array.isArray(body.anomalies) ? body.anomalies : [];

if (anomalies.length === 0) {
  throw new Error('Payload contains no anomalies — model should only call this webhook when an anomaly is detected');
}

// Recompute highest_severity in case the model omitted it
const highest = body.highest_severity
  || (anomalies.some(a => a.severity === 'HIGH')   ? 'HIGH'
    : anomalies.some(a => a.severity === 'MEDIUM') ? 'MEDIUM'
    : 'LOW');

return [{ json: {
  device_id:    body.device_id    || 'esp32_node_01',
  site:         body.site         || 'insat_lab_zone_a',
  timestamp:    body.timestamp    || new Date().toISOString(),
  fw_version:   body.fw_version   || 'N/A',
  uptime_s:     body.uptime_s     ?? 0,
  rssi:         body.rssi         ?? null,
  status:       body.status       || 'anomaly',
  model_name:   body.model_name   || null,
  model_score:  body.model_score  ?? null,
  temp_ds18b20: body.temp_ds18b20 ?? null,
  temp_bme280:  body.temp_bme280  ?? null,
  avg_temp:     body.avg_temp     ?? null,
  humidity:     body.humidity     ?? null,
  pressure:     body.pressure     ?? null,
  temp_drift:   body.temp_drift   ?? null,
  anomalies,
  anomaly_count:    anomalies.length,
  has_anomalies:    true,
  highest_severity: highest
}}];
